# Source of mobile-development/quiz.json (English + Bahasa Indonesia).
# A plain string means "same in both languages" (technical terms). A pair (en, id) is translated.
# Edit this file, then run:  python3 tools/mobile-development/build.py

def Q(src, q, correct, wrongs, why, code=None):
    return dict(kind="mcq", src=src, q=q, correct=correct, wrongs=wrongs, why=why, code=code)


def FILL(src, q, accept, why=None):
    return dict(kind="fill", src=src, q=q, accept=accept, why=why)


def OPEN(src, q, model):
    return dict(kind="open", src=src, q=q, model=model)


def FIXED(src, q, options, answer, why):
    """Options keep the order of the original paper (no shuffle)."""
    return dict(kind="fixed", src=src, q=q, options=options, answer=answer, why=why)


